// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 amount) internal {
        vm.assume(amount <= c.totalSupply());
        uint256 beforeSupply;
        try c.totalSupply() returns (uint256 __r) { beforeSupply = __r; } catch { return; }
        try c.burn(amount) {} catch { return; }
        assertTrue(c.totalSupply() == beforeSupply - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
